def cos(a,b): return float(a@b/(np.linalg.norm(a)*np.linalg.norm(b)+1e-9))
# b_hat from earlier loop analysis
acts3=[np.load(f'/work/fwd_3/mlp_act_L{L}.npy').astype(np.float32) for L in range(24)]
waits={13784,13428,3655}
