for t in range(3):
    for i in range(lengths[t]-1):
        if ids[t][i+1] in waits: loop_mask[t,i]=True
normal_mask=np.zeros((3,1256),bool); normal_mask[1,238:502]=True; normal_mask[2,1233:1256]=True; normal_mask[1,0:237]=True; normal_mask[2,0:800]=True
for L in range(24):
    a=acts3[L]; bhat=a[loop_mask].mean(0)-a[normal_mask].mean(0)
